#include <stdlib.h>
#include <string.h>
#include <omp.h>

#define MR 6
#define NR 16
#define KC 256
#define MC 96
#define NC 512

typedef float v8 __attribute__((vector_size(32)));

static inline v8 loadu(const float *p) { v8 v; memcpy(&v, p, sizeof v); return v; }
static inline void storeu(float *p, v8 v) { memcpy(p, &v, sizeof v); }

static void kernel(int kc, const float *restrict a, const float *restrict b,
                   float *restrict c, int ldc, int mr, int nr, int first)
{
    v8 c0a = {0}, c0b = {0}, c1a = {0}, c1b = {0}, c2a = {0}, c2b = {0};
    v8 c3a = {0}, c3b = {0}, c4a = {0}, c4b = {0}, c5a = {0}, c5b = {0};

    for (int k = 0; k < kc; k++) {
        v8 b0 = *(const v8 *)(b + 16 * k);
        v8 b1 = *(const v8 *)(b + 16 * k + 8);
        const float *ap = a + 6 * k;
        float a0 = ap[0], a1 = ap[1], a2 = ap[2], a3 = ap[3], a4 = ap[4], a5 = ap[5];
        c0a += b0 * a0; c0b += b1 * a0;
        c1a += b0 * a1; c1b += b1 * a1;
        c2a += b0 * a2; c2b += b1 * a2;
        c3a += b0 * a3; c3b += b1 * a3;
        c4a += b0 * a4; c4b += b1 * a4;
        c5a += b0 * a5; c5b += b1 * a5;
    }

    v8 acc[6][2] = {{c0a, c0b}, {c1a, c1b}, {c2a, c2b},
                    {c3a, c3b}, {c4a, c4b}, {c5a, c5b}};

    if (mr == MR && nr == NR) {
        for (int r = 0; r < MR; r++) {
            float *cr = c + (size_t)r * ldc;
            if (first) {
                storeu(cr, acc[r][0]);
                storeu(cr + 8, acc[r][1]);
            } else {
                storeu(cr, loadu(cr) + acc[r][0]);
                storeu(cr + 8, loadu(cr + 8) + acc[r][1]);
            }
        }
    } else {
        float tmp[MR][NR];
        for (int r = 0; r < MR; r++) {
            memcpy(&tmp[r][0], &acc[r][0], sizeof(v8));
            memcpy(&tmp[r][8], &acc[r][1], sizeof(v8));
        }
        for (int r = 0; r < mr; r++) {
            float *cr = c + (size_t)r * ldc;
            if (first)
                for (int j = 0; j < nr; j++) cr[j] = tmp[r][j];
            else
                for (int j = 0; j < nr; j++) cr[j] += tmp[r][j];
        }
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;

    int npanels = (n + NR - 1) / NR;
    size_t bsz = (size_t)KC * npanels * NR * sizeof(float);
    bsz = (bsz + 63) & ~(size_t)63;
    float *Bp = (float *)aligned_alloc(64, bsz);

    int mblocks = (n + MC - 1) / MC;
    int nblocks = (n + NC - 1) / NC;
    int ntasks = mblocks * nblocks;

    #pragma omp parallel
    {
        size_t asz = (size_t)MC * KC * sizeof(float);
        float *Ap = (float *)aligned_alloc(64, asz);

        for (int k0 = 0; k0 < n; k0 += KC) {
            int kc = n - k0 < KC ? n - k0 : KC;
            int first = (k0 == 0);

            #pragma omp for schedule(static)
            for (int p = 0; p < npanels; p++) {
                float *dst = Bp + (size_t)p * kc * NR;
                int j0 = p * NR;
                int w = n - j0 < NR ? n - j0 : NR;
                for (int k = 0; k < kc; k++) {
                    const float *src = B + (size_t)(k0 + k) * n + j0;
                    float *d = dst + (size_t)k * NR;
                    if (w == NR) {
                        memcpy(d, src, NR * sizeof(float));
                    } else {
                        int j = 0;
                        for (; j < w; j++) d[j] = src[j];
                        for (; j < NR; j++) d[j] = 0.0f;
                    }
                }
            }

            #pragma omp for schedule(dynamic, 1)
            for (int t = 0; t < ntasks; t++) {
                int ib = t / nblocks, jb = t % nblocks;
                int i0 = ib * MC;
                int mc = n - i0 < MC ? n - i0 : MC;
                int jstart = jb * NC;
                int jend = jstart + NC < n ? jstart + NC : n;

                for (int ir = 0; ir < mc; ir += MR) {
                    float *dst = Ap + (size_t)ir * kc;
                    int h = mc - ir < MR ? mc - ir : MR;
                    for (int r = 0; r < MR; r++) {
                        if (r < h) {
                            const float *src = A + (size_t)(i0 + ir + r) * n + k0;
                            for (int k = 0; k < kc; k++) dst[k * MR + r] = src[k];
                        } else {
                            for (int k = 0; k < kc; k++) dst[k * MR + r] = 0.0f;
                        }
                    }
                }

                for (int j = jstart; j < jend; j += NR) {
                    const float *bp = Bp + (size_t)(j / NR) * kc * NR;
                    int nr = n - j < NR ? n - j : NR;
                    for (int ir = 0; ir < mc; ir += MR) {
                        int mr = mc - ir < MR ? mc - ir : MR;
                        kernel(kc, Ap + (size_t)ir * kc, bp,
                               C + (size_t)(i0 + ir) * n + j, n, mr, nr, first);
                    }
                }
            }
        }

        free(Ap);
    }

    free(Bp);
}
